import{_ as n,o as r,c as i,ah as a}from"./chunks/framework.DDXs_i7t.js";const g=JSON.parse('{"title":"Recherche: Die COFAG-Milliarden (Benko & das System Signa)","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/cofag-skandal.md","filePath":"recherche/cofag-skandal.md"}'),t={name:"recherche/cofag-skandal.md"};function s(o,e,l,u,h,d){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="recherche-die-cofag-milliarden-benko-das-system-signa" tabindex="-1">Recherche: Die COFAG-Milliarden (Benko &amp; das System Signa) <a class="header-anchor" href="#recherche-die-cofag-milliarden-benko-das-system-signa" aria-label="Permalink to &quot;Recherche: Die COFAG-Milliarden (Benko &amp; das System Signa)&quot;">​</a></h1><p><strong>Corona-Hilfen als Treibstoff für ein sinkendes Schiff?</strong></p><p>Die COVID-19 Finanzierungsagentur des Bundes (COFAG) wurde während der Pandemie gegründet, um Unternehmen schnell und unbürokratisch zu helfen. In unserer Mockumentary beleuchten wir, wie dieses System von Großinvestoren wie René Benko genutzt wurde, während kleine Betriebe oft monatelang auf Hilfe warteten.</p><hr><h2 id="die-fakten-zur-causa-benko" tabindex="-1">Die Fakten zur Causa Benko <a class="header-anchor" href="#die-fakten-zur-causa-benko" aria-label="Permalink to &quot;Die Fakten zur Causa Benko&quot;">​</a></h2><h3 id="_1-das-18-7-millionen-paket" tabindex="-1">1. Das 18,7-Millionen-Paket <a class="header-anchor" href="#_1-das-18-7-millionen-paket" aria-label="Permalink to &quot;1. Das 18,7-Millionen-Paket&quot;">​</a></h3><p>Unternehmen aus dem Signa-Netzwerk erhielten insgesamt mindestens <strong>18,7 Millionen Euro</strong> an Förderungen von der COFAG.</p><ul><li><strong>EU-Limit überschritten?</strong> Die Opposition kritisiert, dass damit das EU-weite Limit von 14 Millionen Euro pro Unternehmensverbund deutlich überschritten wurde.</li><li><strong>Chalet N:</strong> Besonders brisant ist die Förderung für das Luxus-Chalet N in Oberlech, das rund 1,1 Millionen Euro erhielt, obwohl es laut Kritikern faktisch als Privatresidenz fungierte.</li></ul><h3 id="_2-der-„polizeilich-vorgefuhrte-zeuge" tabindex="-1">2. Der „polizeilich vorgeführte“ Zeuge <a class="header-anchor" href="#_2-der-„polizeilich-vorgefuhrte-zeuge" aria-label="Permalink to &quot;2. Der „polizeilich vorgeführte“ Zeuge&quot;">​</a></h3><p>Im Mai 2024 wurde René Benko polizeilich zum Untersuchungsausschuss vorgeführt, nachdem er mehrfach unentschuldigt gefehlt hatte.</p><ul><li><strong>Das Schweigen:</strong> Benko entschlug sich fast allen Fragen unter Verweis auf laufende Ermittlungsverfahren.</li><li><strong>Die Verteidigungslinie:</strong> Er behauptete, lediglich ein „Beirat“ ohne operative Verantwortung gewesen zu sein – eine Aussage, die im krassen Widerspruch zur Wahrnehmung als „faktischer Geschäftsführer“ steht.</li></ul><hr><h2 id="bedeutung-fur-das-„horten-mysterium" tabindex="-1">Bedeutung für das „Horten-Mysterium“ <a class="header-anchor" href="#bedeutung-fur-das-„horten-mysterium" aria-label="Permalink to &quot;Bedeutung für das „Horten-Mysterium“&quot;">​</a></h2><p>Die COFAG-Story ist der moderne Gipfel des Pointillismus.</p><ul><li><strong>Zwei-Klassen-Förderung:</strong> Während Heidi Horten durch Spenden glänzte, sicherte Benko sein Imperium durch den privilegierten Zugang zu Staatsgeldern.</li><li><strong>Die Architektur der Unschuld:</strong> In unserem Drehbuch zeigen wir, wie „Beiräte“ und „Berater“ (wie Benko oder Hortens Umfeld) die Fäden ziehen, ohne jemals formal verantwortlich zu sein.</li></ul><hr><p><em>Quellen: Protokolle des COFAG-Untersuchungsausschusses (2024), Berichte des Rechnungshofs, Analysen von Kontrast.at und Standard.</em></p>',17)])])}const m=n(t,[["render",s]]);export{g as __pageData,m as default};
